CREATE TABLE public.movimentos (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid DEFAULT auth.uid(),
  ordem integer NOT NULL DEFAULT 0,
  mes date NOT NULL,
  data_compra date,
  movimento text NOT NULL,
  categoria text,
  subcategoria text,
  detalhamento text,
  forma_pgto text,
  responsavel text DEFAULT 'RECURSO PROPRIO',
  valor numeric NOT NULL DEFAULT 0,
  formula text,
  situacao text DEFAULT 'Previsto',
  created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.movimentos TO authenticated;
GRANT ALL ON public.movimentos TO service_role;
ALTER TABLE public.movimentos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own movimentos" ON public.movimentos FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE INDEX movimentos_user_mes_idx ON public.movimentos (user_id, mes);

CREATE TABLE public.cartoes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid DEFAULT auth.uid(),
  nome text NOT NULL,
  banco text,
  vencimento integer NOT NULL CHECK (vencimento BETWEEN 1 AND 31),
  limite numeric,
  cor text DEFAULT 'chart-1',
  created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cartoes TO authenticated;
GRANT ALL ON public.cartoes TO service_role;
ALTER TABLE public.cartoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own cartoes" ON public.cartoes FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

CREATE TABLE public.faturas (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL DEFAULT auth.uid(),
  cartao text NOT NULL,
  mes date NOT NULL,
  valor numeric NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, cartao, mes)
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.faturas TO authenticated;
GRANT ALL ON public.faturas TO service_role;
ALTER TABLE public.faturas ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own faturas" ON public.faturas FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

CREATE OR REPLACE FUNCTION public.claim_seed_data()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE n integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN RETURN 0; END IF;
  IF EXISTS (SELECT 1 FROM movimentos WHERE user_id = auth.uid()) THEN RETURN 0; END IF;
  UPDATE movimentos SET user_id = auth.uid() WHERE user_id IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  UPDATE cartoes SET user_id = auth.uid() WHERE user_id IS NULL;
  RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.claim_seed_data() FROM public, anon;
GRANT EXECUTE ON FUNCTION public.claim_seed_data() TO authenticated;


) AS v(ordem,mes,movimento,categoria,subcategoria,detalhamento,forma_pgto,responsavel,valor,formula,situacao);